const getVipThemeBg = (theme: string, isLight: boolean) => {
  if (isLight) return '#F2F2F7';
  switch (theme) {
    case 'gold_luxury':
      return '#120F08';
    case 'cyberpunk':
      return '#060B14';
    case 'nebula':
      return '#0E071A';
    case 'oled_black':
      return '#000000';
    case 'default':
    default:
      return '#000000';
  }
};

const getVipThemeCardBg = (theme: string, isLight: boolean) => {
  if (isLight) return '#FFFFFF';
  switch (theme) {
    case 'gold_luxury':
      return '#1D170E';
    case 'cyberpunk':
      return '#0C1524';
    case 'nebula':
      return '#170E28';
    case 'oled_black':
      return '#111111';
    case 'default':
    default:
      return '#1C1C1E';
  }
};

const getVipThemeBorder = (theme: string, isLight: boolean) => {
  if (isLight) return '#E5E5EA';
  switch (theme) {
    case 'gold_luxury':
      return '#382B14';
    case 'cyberpunk':
      return '#172E4D';
    case 'nebula':
      return '#321954';
    case 'oled_black':
      return '#222222';
    case 'default':
    default:
      return '#2C2C2E';
  }
};

