                          height: 180,
                          backgroundColor: '#FFFFFF',
                          borderRadius: 16,
                          marginTop: 18,
                          marginBottom: 14,
                          padding: 12,
                          justifyContent: 'center',
                          alignItems: 'center',
                          borderWidth: 1,
                          borderColor: '#E5E5EA',
                          shadowColor: '#000',
                          shadowOffset: { width: 0, height: 2 },
                          shadowOpacity: 0.1,
                          shadowRadius: 6,
